'use strict';
const C=window.SKAS_CONFIG;
const $=(s,r=document)=>r.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3z M12 6v15',award:'M8 3h8v6a4 4 0 0 1-8 0z M8 5H4v3a4 4 0 0 0 4 4 M16 5h4v3a4 4 0 0 1-4 4 M12 13v7 M8 21h8',heart:'M20.8 4.6a5.4 5.4 0 0 0-7.6 0L12 5.8l-1.2-1.2a5.4 5.4 0 0 0-7.6 7.6L12 21l8.8-8.8a5.4 5.4 0 0 0 0-7.6z',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',check:'M20 6 9 17l-5-5',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',chevron:'m9 5 7 7-7 7',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-4',logout:'M9 21H4V3h5 M12 12h10 M18 8l4 4-4 4',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',print:'M6 9V3h12v6 M6 18H3V9h18v9h-3 M6 14h12v8H6z',menu:'M3 6h18 M3 12h18 M3 18h18',close:'M6 6l12 12 M6 18 18 6',upload:'M12 17V3 M7 8l5-5 5 5 M4 16v5h16v-5',link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-3 3 M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l3-3',edit:'m16 3 5 5-12 12-6 1 1-6z M14 5l5 5',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',refresh:'M20 7a9 9 0 1 0 1 9 M20 3v5h-5',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z M8 12l3 3 5-6',chart:'M4 3v18h17 M8 16v-4 M13 16V8 M18 16V5',info:'M12 11v6 M12 7v.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',mail:'M3 5h18v14H3z M3 5l9 8 9-8'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const statuses=['Draf','Dihantar','Perlu Pembetulan','Disahkan'];
const roleLabel={admin:'Pentadbir',penyelaras:'Penyelaras',guru:'Guru / Pegawai'};
const badge=s=>`<span class="tag ${s==='Disahkan'?'green':s==='Dihantar'?'blue':s==='Perlu Pembetulan'?'red':'orange'}">${esc(s)}</span>`;
const stdIcon=id=>id==='3.1'?'book':id==='3.2'?'award':'heart';
const active=x=>x.active!==false&&x.active!=='false';
const state={token:'',user:null,data:null,demo:false,page:'dashboard',standard:'',subtopic:'',record:'',settingsTab:'users',year:String(new Date().getFullYear()),filters:{search:'',standard:'',subtopic:'',status:'',unit:'',officer:'',start:'',end:''}};
let installPrompt=null,busyCount=0,toastTimer=null,submitting=false,apiReady=false;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',5000);}
function busy(on,label='Memproses…'){busyCount=Math.max(0,busyCount+(on?1:-1));$('#busy').hidden=!busyCount;$('#busy-label').textContent=label;}
function remember(){if(state.demo)return;try{sessionStorage.setItem('skas-session',JSON.stringify({token:state.token,user:state.user}));}catch{}}
function forget(){try{sessionStorage.removeItem('skas-session');}catch{}}
async function api(action,payload={}){
  if(state.demo)return demoApi(action,payload);
  if(!navigator.onLine)throw new Error('Tiada sambungan Internet. Sambung semula sebelum membaca atau menyimpan data.');
  if(action!=='health'&&!apiReady){const health=await api('health');if(!health.ready)throw new Error('Sila jalankan setupSystem() dalam editor Apps Script dahulu.');apiReady=true;}
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),90000);busy(true,action==='addEvidence'?'Memuat naik evidens…':'Menghubungkan pangkalan data…');
  try{
    const response=await fetch(C.apiUrl,{method:action==='health'?'GET':'POST',redirect:'follow',credentials:'omit',headers:action==='health'?{}:{'Content-Type':'text/plain;charset=utf-8'},body:action==='health'?undefined:JSON.stringify({action,token:state.token,requestId:crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random(),...payload}),signal:controller.signal,cache:'no-store'});
    const raw=await response.text();let result;try{result=JSON.parse(raw);}catch{throw new Error('Pelayan tidak memulangkan JSON. Pastikan Code.gs baharu telah dideploy sebagai Web app, Execute as: Me, akses: Anyone.');}
    if(!response.ok||!result.ok){if(result.code==='UNAUTHORIZED'&&action!=='login'){state.token='';state.user=null;state.data=null;forget();renderLogin();}throw new Error(result.error||'Sambungan pelayan gagal.');}
    if(action==='health'&&result.app!=='SKAS')throw new Error('URL ini belum menggunakan Apps Script SK@S baharu.');
    return action==='health'?result:result.data;
  }catch(e){if(e.name==='AbortError')throw new Error('Masa menunggu tamat. Muat semula rekod untuk menyemak hasil sebelum cuba menyimpan lagi.');if(e instanceof TypeError)throw new Error('Tidak dapat menghubungi Apps Script. Semak Internet, URL /exec dan akses deployment Anyone.');throw e;}finally{clearTimeout(timer);busy(false);}
}
async function load(){const data=await api('bootstrap');state.data=data;state.user=data.user;remember();renderShell();}
const standardBy=id=>state.data?.standards.find(s=>s.id===id);
const subBy=id=>state.data?.subtopics.find(s=>s.id===id);
const recordBy=id=>state.data?.records.find(r=>r.id===id);
const currentRecords=()=>state.data.records.filter(r=>String(r.year)===state.year);
const canReview=r=>state.user.role==='admin'||state.user.role==='penyelaras'&&state.user.scopes.includes(r.standardId);
const canEdit=r=>state.user.role==='admin'||(r.ownerId===state.user.id||r.assignedTo===state.user.id||canReview(r))&&['Draf','Perlu Pembetulan'].includes(r.status);
const initials=name=>(name||'S').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();
const date=v=>v?new Date(v.length===10?v+'T00:00:00':v).toLocaleDateString('ms-MY',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kuala_Lumpur'}):'—';
const safeURL=url=>{try{const u=new URL(url);return u.protocol==='https:'?esc(u.href):'#';}catch{return '#';}};
function logo(){return esc(state.data?.settings?.logo||C.logo);}
function school(){return state.data?.settings?.school||C.school;}
function empty(title='Belum ada rekod',desc='Tambah rekod pertama untuk memulakan pengurusan.'){return `<div class="empty">${icon('file')}<h3>${esc(title)}</h3><p>${esc(desc)}</p></div>`;}
function header(title,subtitle,actions=''){return `<div class="page-title"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="row wrap">${actions}</div></div>`;}
function button(label,action,ico='',cls='',id=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${ico?icon(ico):''}${esc(label)}</button>`;}
function progress(std){const subs=state.data.subtopics.filter(s=>s.standardId===std&&active(s)),rs=currentRecords();const done=subs.filter(s=>rs.some(r=>r.subtopicId===s.id&&r.status==='Disahkan')).length;return {done,total:subs.length,percent:subs.length?Math.round(done/subs.length*100):0};}
function renderLogin(){
  $('#app').innerHTML=`<div class="login fade"><section class="login-visual"><div class="login-brand"><img class="logo" src="${esc(C.logo)}" alt="Lencana SK Sungai Tiram"><div><b>SK<span style="color:#c7deb0">@</span>S</b><small>SEKOLAH KEBANGSAAN SUNGAI TIRAM</small></div></div><div class="login-headline"><div class="eyebrow" style="color:#b6d2bb;margin-bottom:15px">TERATUR. TERHUBUNG. TERURUS.</div><h1>Pengurusan sekolah,<br><span>lebih bermakna.</span></h1><p>Satu ruang untuk merancang, merekod dan memantau. Bersama membina pengurusan sekolah yang lebih cemerlang.</p><div class="login-chips"><span>01 &nbsp; Kurikulum</span><span>02 &nbsp; Kokurikulum</span><span>03 &nbsp; Hal Ehwal Murid</span></div><div class="login-graphic"><div class="row between"><span class="eyebrow">EKOSISTEM PENGURUSAN SEKOLAH</span>${icon('shield')}</div><div class="login-graphic-row"><div class="login-mini"><small>Perancangan</small><span><i style="width:85%"></i></span></div><div class="login-mini"><small>Pelaksanaan</small><span><i style="width:68%"></i></span></div><div class="login-mini"><small>Evidens</small><span><i style="width:92%"></i></span></div></div><small style="display:block;color:#abc2c6;font-size:8px;margin-top:15px">Ilustrasi aliran kerja · bukan data pencapaian</small></div></div><div class="login-footer">SK@S &nbsp; / &nbsp; Sistem Pengurusan Sekolah</div></section><main class="login-content" id="main"><div class="login-form"><span class="eyebrow" style="color:#6b9981">SELAMAT DATANG KEMBALI</span><h2>Log masuk ke SK@S</h2><p>Urus tugas dan evidens sekolah dalam satu tempat.</p><form id="login-form"><div class="form-field"><label for="username">Nama pengguna</label><input id="username" name="username" autocomplete="username" required placeholder="Masukkan nama pengguna"></div><div class="form-field"><label for="password">Kata laluan</label><input id="password" name="password" type="password" autocomplete="current-password" required placeholder="Masukkan kata laluan"></div><div id="login-error" class="login-error" role="alert"></div><button class="btn primary full" type="submit">Log masuk ${icon('arrow')}</button></form><p class="login-help">Akaun disediakan oleh pentadbir sekolah.</p><div class="login-divider">TEROKAI SISTEM</div>${button('Lihat demonstrasi','demo','grid','full')}<div class="row" style="justify-content:center;margin-top:13px">${button('Uji sambungan','health','refresh','ghost small')}${button('Pasang aplikasi','install','download','ghost small')}</div><div class="status-line"><span class="status-dot"></span>SK Sungai Tiram · Versi ${esc(C.version)}</div></div></main></div>`;
}
function navButton(page,label,ico,extra=''){return `<button class="nav-btn ${state.page===page?'active':''}" data-action="nav" data-page="${page}">${icon(ico)}<span>${label}</span>${extra}</button>`;}
function renderShell(){
  const u=state.user,years=[...new Set([String(new Date().getFullYear()),state.year,...state.data.records.map(r=>String(r.year))])].sort().reverse();
  $('#app').innerHTML=`<div class="shell">${state.demo?'<div class="sr-only">Mod demonstrasi. Semua data contoh.</div>':''}<div class="mobile-shade" data-action="menu"></div><aside class="sidebar"><div class="brand row"><img class="logo" src="${logo()}" alt="Lencana sekolah"><div><strong>SK<span>@</span>S</strong><small>PENGURUSAN SEKOLAH</small></div></div><div class="school-pill"><b>${esc(school())}</b><small>Satu sistem. Tiga bidang pengurusan.</small></div><div class="nav-group"><p class="nav-label">RUANG KERJA</p>${navButton('dashboard','Dashboard','grid')}${navButton('standards','Standard & Subtopik','book')}${navButton('records','Rekod Pelaksanaan','file',`<span class="count">${currentRecords().length}</span>`)}${navButton('reports','Laporan & Analisis','chart')}</div><div class="nav-group"><p class="nav-label">PENGURUSAN</p>${u.role==='admin'?navButton('settings','Tetapan Sistem','settings'):''}<button class="nav-btn" data-action="password">${icon('shield')}<span>Tukar Kata Laluan</span></button><button class="nav-btn" data-action="install">${icon('download')}<span>Pasang Aplikasi</span></button></div><div class="nav-bottom"><button class="nav-btn" data-action="logout">${icon('logout')}<span>${state.demo?'Keluar Demonstrasi':'Log Keluar'}</span></button><div class="sidebar-note"><b>Pengurusan yang terancang.</b><span class="muted">Rekod hari ini, rujukan masa hadapan.</span></div></div></aside><div class="workspace"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Buka menu">${icon('menu')}</button><form id="global-search" class="search">${icon('search')}<input name="query" aria-label="Carian rekod" placeholder="Cari rekod sekolah…" style="border:0;background:none;outline:0;width:100%;font-size:11px"></form><div class="top-actions"><span class="network-state">${state.demo?'Mod Demo':navigator.onLine?'● Dalam talian':'● Luar talian'}</span><label class="sr-only" for="school-year">Tahun pengurusan</label><select id="school-year">${years.map(y=>`<option ${y===state.year?'selected':''}>${esc(y)}</option>`).join('')}</select><button class="icon-btn" data-action="refresh" aria-label="Muat semula data">${icon('refresh')}</button><div class="row"><div class="avatar">${esc(initials(u.name))}</div><div class="profile-label"><div class="profile-name">${esc(u.name)}</div><div class="profile-role">${roleLabel[u.role]}</div></div></div></div></header>${state.demo?'<div class="demo-banner">MOD DEMONSTRASI · Data contoh sahaja. Perubahan tidak dihantar ke Google Sheets.</div>':''}${!navigator.onLine?'<div class="offline-banner">Luar talian · Kerangka aplikasi tersedia. Data dan simpanan memerlukan Internet.</div>':''}<main class="main" id="main"></main></div></div>`;
  renderPage();
}
function renderPage(){
  if(!state.data)return;document.body.classList.remove('menu-open');
  const main=$('#main');main.className='main fade';const page=state.page;
  main.innerHTML=`<div class="breadcrumb"><button data-action="nav" data-page="dashboard">Utama</button>${page!=='dashboard'?icon('chevron')+`<span>${({standards:'Standard & Subtopik',standard:'Standard',subtopic:'Subtopik',records:'Rekod Pelaksanaan',detail:'Butiran Rekod',reports:'Laporan & Analisis',settings:'Tetapan Sistem'})[page]||''}</span>`:''}</div>`+(page==='dashboard'?dashboard():page==='standards'?standardsPage():page==='standard'?standardPage():page==='subtopic'?subtopicPage():page==='records'?recordsPage():page==='detail'?detailPage():page==='reports'?reportsPage():page==='settings'&&state.user.role==='admin'?settingsPage():empty())+`<footer class="footer"><span>© ${new Date().getFullYear()} SK@S · SK Sungai Tiram</span><span>Teratur. Terhubung. Terurus.</span></footer>`;
}
function standardCards(){return `<div class="standard-grid">${state.data.standards.filter(active).map(s=>{const p=progress(s.id),n=currentRecords().filter(r=>r.standardId===s.id).length;return `<button class="standard-card s${esc(s.id.replace('.',''))}" data-action="standard" data-id="${esc(s.id)}"><div class="standard-top"><span class="standard-symbol">${icon(stdIcon(s.id))}</span><span class="standard-code">STANDARD ${esc(s.code)}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="standard-foot"><span>${p.total} subtopik &nbsp;·&nbsp; ${n} rekod</span>${icon('arrow')}</div><div class="progress-track"><span style="width:${p.percent}%"></span></div></button>`;}).join('')}</div>`;}
function dashboard(){
  const rs=currentRecords(),verified=rs.filter(r=>r.status==='Disahkan').length,pending=rs.filter(r=>r.status==='Dihantar').length,ev=rs.reduce((n,r)=>n+r.evidence.length,0);
  return header('Dashboard','Gambaran pengurusan sekolah anda, dalam satu pandangan.',button('Tambah Rekod','create','plus','primary'))+`<section class="hero"><div class="hero-copy"><div class="eyebrow">BERSAMA MEMBINA KECEMERLANGAN</div><h2>Setiap usaha direkod.<br>Setiap kemajuan dihargai.</h2><p>Selaraskan pengurusan kurikulum, kokurikulum dan hal ehwal murid dengan lebih tersusun.</p>${button('Terokai Standard','nav-standards','arrow')}</div><div class="hero-art" aria-hidden="true"><div class="art-card main-art"><div class="row between"><span style="font-size:8px;font-weight:800">RUMUSAN PENGURUSAN</span>${icon('chart')}</div><div class="line"></div><div class="line short"></div><div class="art-bars"><i style="height:52%"></i><i style="height:83%"></i><i style="height:66%"></i><i style="height:97%"></i></div><div class="line short"></div></div><div class="art-card float-art"><span class="art-circle">${icon('check')}</span><div><b>Evidens tersusun</b><div style="font-size:7px;color:#8ba19f">Rancang · Laksana · Semak</div></div></div></div></section><div class="metrics">${[['Jumlah Rekod',rs.length,'file','Semua rekod tahun dipilih',''],['Menunggu Semakan',pending,'clock','Rekod telah dihantar','Dihantar'],['Rekod Disahkan',verified,'check','Semakan telah selesai','Disahkan'],['Jumlah Evidens',ev,'link','Lampiran & pautan berkaitan','evidence']].map(a=>`<button class="metric" data-action="metric" data-status="${a[4]}"><div class="metric-top">${a[0]}<span class="metric-icon">${icon(a[2])}</span></div><strong>${a[1]}</strong><small>${a[3]}</small></button>`).join('')}</div><div class="section-title"><h3>Bidang pengurusan</h3><small>Tiga Standard. Satu matlamat.</small></div>${standardCards()}<div class="dashboard-bottom"><section class="panel"><div class="section-title"><h3>Rekod terkini</h3>${button('Lihat semua','nav-records','arrow','ghost small')}</div>${rs.length?[...rs].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,4).map(r=>`<div class="activity-row"><span class="activity-symbol">${icon(stdIcon(r.standardId))}</span><div class="spacer"><button class="title-btn" style="border:0;background:none;text-align:left;padding:0;color:inherit" data-action="detail" data-id="${r.id}"><div class="activity-title">${esc(r.title)}</div></button><div class="activity-meta">Standard ${esc(standardBy(r.standardId)?.code||r.standardId)} · ${date(r.startDate)}</div></div>${badge(r.status)}</div>`).join(''):empty('Mulakan rekod pertama anda','Rekod baharu akan muncul di sini.')}</section><section class="panel"><div class="section-title"><h3>Liputan subtopik</h3><span class="tag">${state.year}</span></div>${state.data.standards.filter(active).map(s=>{const p=progress(s.id);return `<div class="chart-row"><div class="chart-label"><span>${esc(s.title.replace('Pengurusan ',''))}</span><b>${p.percent}%</b></div><div class="chart-track" role="progressbar" aria-label="Liputan ${esc(s.title)}" aria-valuenow="${p.percent}" aria-valuemin="0" aria-valuemax="100"><i style="width:${p.percent}%"></i></div></div>`;}).join('')}<div class="chart-note">Subtopik dengan sekurang-kurangnya satu rekod disahkan ÷ jumlah subtopik aktif × 100%. Berdasarkan rekod yang boleh anda akses. Bukan skor rasmi SK@S.</div></section></div>`;
}
function standardsPage(){return header('Standard & Subtopik','Pilih bidang pengurusan untuk meneroka subtopik dan evidens.')+standardCards()+`<div class="notice">Struktur awal berdasarkan maklumat yang dibekalkan. Kod, penerangan dan senarai semak boleh disunting oleh pentadbir.</div>`;}
function standardPage(){const s=standardBy(state.standard);if(!s)return empty('Standard tidak ditemui');return header(s.title,`Standard ${s.code} · ${s.description}`,button('Tambah Rekod','create','plus','primary'))+`<div class="sub-grid">${state.data.subtopics.filter(t=>t.standardId===s.id&&active(t)).map(t=>{const rs=currentRecords().filter(r=>r.subtopicId===t.id);return `<button class="sub-card" data-action="subtopic" data-id="${t.id}"><div class="eyebrow">${esc(t.code)}</div><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p><footer><span>${rs.length} rekod · ${rs.reduce((n,r)=>n+r.evidence.length,0)} evidens</span>${icon('arrow')}</footer></button>`;}).join('')}</div>`;}
function subtopicPage(){const t=subBy(state.subtopic);if(!t)return empty('Subtopik tidak ditemui');const rs=currentRecords().filter(r=>r.subtopicId===t.id);return header(t.title,`${t.code} · ${standardBy(t.standardId)?.title||''}`,button('Tambah Rekod','create','plus','primary'))+`<div class="panel" style="margin-bottom:20px"><p class="muted" style="font-size:12px">${esc(t.description)}</p><div class="notice">Pegawai bertanggungjawab: <b>${esc(t.officer||'Belum ditetapkan')}</b></div><h3 style="font-size:13px;margin-bottom:8px">Senarai semak evidens</h3>${t.checklist.map(c=>`<div class="check-row">${icon('file')}<span>${esc(c)}</span></div>`).join('')}</div>`+recordsTable(rs);}
function option(value,label,selected){return `<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`;}
function filtersHTML(){const f=state.filters;return `<div class="filters"><div><label class="filter-label" for="f-search">Carian tajuk / ringkasan</label><input id="f-search" data-filter="search" value="${esc(f.search)}" placeholder="Cari rekod…"></div><div><label class="filter-label" for="f-standard">Standard</label><select id="f-standard" data-filter="standard">${option('','Semua Standard',f.standard)}${state.data.standards.map(s=>option(s.id,s.code+' · '+s.title,f.standard)).join('')}</select></div><div><label class="filter-label" for="f-subtopic">Subtopik</label><select id="f-subtopic" data-filter="subtopic">${option('','Semua Subtopik',f.subtopic)}${state.data.subtopics.filter(t=>!f.standard||t.standardId===f.standard).map(t=>option(t.id,t.code+' · '+t.title,f.subtopic)).join('')}</select></div><div><label class="filter-label" for="f-status">Status</label><select id="f-status" data-filter="status">${option('','Semua Status',f.status)}${statuses.map(s=>option(s,s,f.status)).join('')}${option('evidence','Mempunyai Evidens',f.status)}</select></div></div><div class="filters secondary"><div><label class="filter-label" for="f-unit">Unit / Panitia</label><select id="f-unit" data-filter="unit">${option('','Semua Unit',f.unit)}${[...new Set(currentRecords().map(r=>r.unit).filter(Boolean))].sort().map(n=>option(n,n,f.unit)).join('')}</select></div><div><label class="filter-label" for="f-officer">Pegawai</label><input id="f-officer" data-filter="officer" value="${esc(f.officer)}" placeholder="Nama pegawai"></div><div><label class="filter-label" for="f-start">Tarikh mula dari</label><input id="f-start" type="date" data-filter="start" value="${esc(f.start)}"></div><div><label class="filter-label" for="f-end">Tarikh mula hingga</label><input id="f-end" type="date" data-filter="end" value="${esc(f.end)}"></div></div>`;}
function filteredRecords(){const f=state.filters;return currentRecords().filter(r=>(!f.search||(r.title+' '+r.summary).toLowerCase().includes(f.search.toLowerCase()))&&(!f.standard||r.standardId===f.standard)&&(!f.subtopic||r.subtopicId===f.subtopic)&&(!f.status||(f.status==='evidence'?r.evidence.length>0:r.status===f.status))&&(!f.unit||r.unit===f.unit)&&(!f.officer||r.officer.toLowerCase().includes(f.officer.toLowerCase()))&&(!f.start||r.startDate>=f.start)&&(!f.end||r.startDate<=f.end)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));}
function recordsTable(rs){return rs.length?`<div class="record-count">${rs.length} rekod dipaparkan · Tahun ${esc(state.year)}</div><div class="table-wrap"><table><thead><tr><th>Bil.</th><th>Tajuk / Subtopik</th><th>Pegawai</th><th>Tarikh</th><th>Evidens</th><th>Status</th><th><span class="sr-only">Tindakan</span></th></tr></thead><tbody>${rs.map((r,i)=>`<tr><td>${i+1}</td><td style="min-width:200px;max-width:360px"><button class="title-btn" data-action="detail" data-id="${r.id}">${esc(r.title)}</button><div class="activity-meta">${esc(subBy(r.subtopicId)?.code||'')} · ${esc(r.unit||'Umum')}</div></td><td>${esc(r.officer)}</td><td style="white-space:nowrap">${date(r.startDate)}</td><td>${r.evidence.length}</td><td>${badge(r.status)}</td><td><button class="icon-btn" data-action="detail" data-id="${r.id}" aria-label="Buka rekod ${esc(r.title)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Tiada rekod untuk dipaparkan','Tambah rekod atau ubah penapis carian anda.');}
function recordsPage(){return header('Rekod Pelaksanaan','Rancang, rekod dan susun evidens aktiviti sekolah.',button('Cetak Senarai','print-list','print')+button('Tambah Rekod','create','plus','primary'))+filtersHTML()+`<div id="records-result">${recordsTable(filteredRecords())}</div>`;}
function detailPage(){const r=recordBy(state.record);if(!r)return empty('Rekod tidak ditemui');const t=subBy(r.subtopicId);return header(r.title,`${t?.code||''} · ${r.unit||'Umum'}`,button('Cetak / PDF','print-record','print','',r.id)+(canEdit(r)?button('Sunting','edit','edit','primary',r.id):''))+`<div class="detail-grid"><div class="panel"><div class="row between" style="margin-bottom:20px"><h3>Maklumat pelaksanaan</h3>${badge(r.status)}</div><dl class="detail-meta">${[['Standard',standardBy(r.standardId)?.title],['Subtopik',t?.title],['Pegawai',r.officer],['Unit / Panitia',r.unit||'—'],['Tarikh mula',date(r.startDate)],['Tarikh tamat',date(r.endDate)],['Tahun',r.year],['Sasaran',r.target||'—']].map(([k,v])=>`<div class="detail-item"><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${[['Objektif',r.objectives],['Ringkasan Pelaksanaan',r.summary],['Pencapaian / Impak',r.impact],['Isu & Tindakan Susulan',r.issues]].map(([k,v])=>`<dl class="detail-item"><dt>${k}</dt><dd>${esc(v||'Belum diisi')}</dd></dl>`).join('')}<div class="row wrap" style="border-top:1px solid #edf1ef;padding-top:18px">${canEdit(r)&&['Draf','Perlu Pembetulan'].includes(r.status)?button('Hantar untuk Semakan','submit-record','check','teal',r.id):''}${canReview(r)&&r.status!=='Draf'?button('Buka Semula','reopen','refresh','',r.id):''}${state.user.role==='admin'?button('Padam Rekod','delete-record','trash','danger',r.id):''}</div><small style="display:block;margin-top:15px">Dikemas kini ${date(r.updatedAt)} · Versi rekod ${r.revision}</small></div><div><section class="panel" style="margin-bottom:18px"><div class="section-title"><h3>Evidens</h3>${canEdit(r)?button('Tambah','evidence','plus','small',r.id):''}</div>${r.evidence.length?r.evidence.map(e=>`<div class="evidence">${icon(e.mimeType==='link'?'link':'file')}<a href="${safeURL(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.name)}<small style="display:block">${e.mimeType==='link'?'Pautan dokumen':Math.round(Number(e.size)/1024)+' KB · Google Drive'}</small></a>${canEdit(r)?`<button class="icon-btn" data-action="remove-evidence" data-id="${e.id}" data-record="${r.id}" aria-label="Buang evidens">${icon('close')}</button>`:''}</div>`).join(''):'<p class="muted" style="font-size:11px">Belum ada evidens. Simpan fail atau pautan selepas merekod pelaksanaan.</p>'}<small style="display:block;margin-top:12px">Akses fail Google Drive mengikut tetapan perkongsian pemilik.</small></section><section class="panel" style="margin-bottom:18px"><h3 style="margin-bottom:13px">Senarai semak</h3>${(t?.checklist||[]).map(c=>`<div class="check-row" style="color:${r.checklist.includes(c)?'#438d6f':'#9aabb0'}">${icon(r.checklist.includes(c)?'check':'file')}<span>${esc(c)}</span></div>`).join('')}</section><section class="panel"><h3 style="margin-bottom:12px">Semakan & Maklum Balas</h3>${state.data.reviews.filter(s=>s.recordId===r.id).map(s=>`<div class="review-item">${badge(s.status)}<p>${esc(s.feedback||'Rekod disahkan.')}</p><small>${esc(s.reviewerName)} · ${date(s.createdAt)}</small></div>`).join('')||'<p class="muted" style="font-size:11px">Belum ada semakan.</p>'}${canReview(r)&&r.status==='Dihantar'?`<div style="margin-top:15px">${button('Semak Rekod','review','check','teal full',r.id)}</div>`:''}</section></div></div>`;}
function reportsPage(){return header('Laporan & Analisis','Jana rumusan dan cetak laporan mengikut rekod yang boleh anda akses.')+filtersHTML()+`<div class="notice">Laporan menggunakan tahun dan penapis di atas. Untuk PDF, pilih <b>Save as PDF / Simpan sebagai PDF</b> dalam dialog cetakan.</div><div class="report-options">${[['Rumusan Keseluruhan','Kemajuan subtopik dan ringkasan status setiap Standard.','summary','chart'],['Senarai Rekod','Jadual pelaksanaan lengkap mengikut penapis.','list','file'],['Senarai Evidens','Daftar lampiran dan pautan evidens bagi rekod terpilih.','evidence','link'],['Rekod Belum Lengkap','Rekod belum disahkan, tanpa evidens atau senarai semak belum lengkap.','incomplete','clock'],['Laporan Program','Butiran pelaksanaan, impak dan evidens setiap rekod.','program','book']].map(a=>`<button class="report-option" data-action="report" data-type="${a[2]}">${icon(a[3])}<h3>${a[0]}</h3><p>${a[1]}</p></button>`).join('')}</div>`;}
function settingsPage(){const tab=state.settingsTab;return header('Tetapan Sistem','Urus pengguna, struktur pengurusan dan identiti sekolah.')+`<div class="settings-tabs">${[['users','Pengguna'],['Standard','Standard'],['Subtopik','Subtopik'],['Unit_Panitia','Unit / Panitia'],['school','Sekolah'],['logs','Log Aktiviti'],['connection','Sambungan']].map(([id,label])=>`<button class="btn small ${tab===id?'active':''}" data-action="settings-tab" data-id="${id}">${label}</button>`).join('')}</div><section class="panel">${settingsContent(tab)}</section>`;}
function settingsContent(tab){
  if(tab==='users')return `<div class="section-title"><h3>Pengguna Sistem</h3>${button('Tambah Pengguna','new-user','plus','primary small')}</div><div id="users-list">${state.data.users.map(u=>`<div class="user-card"><div class="row"><span class="avatar">${esc(initials(u.name))}</span><div><p>${esc(u.name)} ${u.active===false?'<span class="tag red">Tidak aktif</span>':''}</p><small>${esc(u.username)} · ${roleLabel[u.role]}${u.role==='penyelaras'?' · '+esc(u.scopes.join(', ')):''}</small></div></div>${button('Sunting','edit-user','edit','small',u.id)}</div>`).join('')}</div><div class="notice">Pengguna baharu menerima kata laluan sementara yang ditetapkan pentadbir dan perlu menukarnya selepas log masuk.</div>`;
  if(['Standard','Subtopik','Unit_Panitia'].includes(tab)){const list=tab==='Standard'?state.data.standards:tab==='Subtopik'?state.data.subtopics:state.data.units;return `<div class="section-title"><h3>${tab==='Unit_Panitia'?'Unit / Panitia':tab}</h3><button class="btn primary small" data-action="new-master" data-table="${tab}">${icon('plus')}Tambah</button></div>${list.map(x=>`<div class="user-card"><div><p>${esc(x.code||'')} ${esc(x.title||x.name)}</p><small>${esc(x.standardId?standardBy(x.standardId)?.title||'':'')}${!active(x)?' · Tidak aktif':''}</small></div><button class="btn small" data-action="edit-master" data-table="${tab}" data-id="${x.id}">${icon('edit')}Sunting</button></div>`).join('')}`;}
  if(tab==='school'){const s=state.data.settings;return `<h3 style="margin-bottom:20px">Identiti Sekolah</h3><form id="school-form"><div class="form-field"><label for="school-name">Nama sekolah</label><input id="school-name" name="school" required value="${esc(s.school||C.school)}"></div><div class="form-field"><label for="school-logo">Pautan logo</label><input id="school-logo" name="logo" value="${esc(s.logo||C.logo)}"><small>Gunakan pautan HTTPS atau assets/lencana.png untuk lencana yang dibekalkan.</small></div><div class="form-field"><label for="settings-year">Tahun lalai</label><input id="settings-year" type="number" min="2000" max="2099" name="year" required value="${esc(s.year||state.year)}"></div><div class="form-error" role="alert"></div><button class="btn primary">Simpan Tetapan</button></form>`;}
  if(tab==='logs')return state.data.logs.length?`<div class="table-wrap"><table><thead><tr><th>Tarikh</th><th>Pengguna</th><th>Aktiviti</th></tr></thead><tbody>${state.data.logs.map(l=>`<tr><td>${date(l.createdAt)}</td><td>${esc(l.name)}</td><td>${esc(l.action)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada aktiviti');
  return `<h3>Sambungan Google</h3><div class="notice">Endpoint telah ditetapkan dalam config.js. Selepas menggantikan Code.gs, kemas kini deployment Apps Script kepada versi baharu.</div><dl><div class="detail-item"><dt>Web App</dt><dd style="font-size:10px">${esc(C.apiUrl)}</dd></div><div class="detail-item"><dt>CSV rujukan yang dibekalkan</dt><dd style="font-size:10px;word-break:break-all">${esc(C.csvUrl)}</dd></div></dl><div class="row wrap">${button('Uji Sambungan','health','refresh','primary')}${button('Semak CSV Rujukan','csv','file')}</div><p class="muted" style="font-size:11px;margin-top:15px">CSV hanya untuk rujukan pentadbir. Rekod, pengguna dan evidens diurus melalui API yang memerlukan log masuk.</p>`;
}
function openModal(title,html){const d=$('#modal');d.innerHTML=`<header class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Tutup">${icon('close')}</button></header><div class="modal-body">${html}</div>`;if(!d.open)d.showModal();}
function closeModal(){if(state.user?.forcePassword)return;$('#modal').close();}
function actionsHTML(label='Simpan'){return `<div class="form-error" role="alert"></div><div class="modal-actions">${button('Batal','close-modal')}<button type="submit" class="btn primary">${icon('check')}${label}</button></div>`;}
function field(label,name,value='',type='text',required=false,extra=''){const id='field-'+name;return `<div class="form-field ${extra}"><label for="${id}">${label}${required?' *':''}</label>${type==='textarea'?`<textarea id="${id}" name="${name}" ${required?'required':''} maxlength="4000">${esc(value)}</textarea>`:`<input id="${id}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'minlength="12" autocomplete="new-password"':''}>`}</div>`;}
function selectField(label,name,options,extra=''){return `<div class="form-field ${extra}"><label for="field-${name}">${label}</label><select id="field-${name}" name="${name}">${options}</select></div>`;}
function showRecordForm(id){
  const r=id?recordBy(id):null;if(r&&!canEdit(r))return toast('Rekod tidak boleh disunting.',true);const sub=r?subBy(r.subtopicId):state.page==='subtopic'?subBy(state.subtopic):null;
  const s=r?.standardId||sub?.standardId||state.standard||state.data.standards.find(active)?.id;const now=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kuala_Lumpur'});
  openModal(r?'Sunting Rekod':'Tambah Rekod Pelaksanaan',`<form id="record-form" data-id="${esc(id||'')}" data-revision="${r?.revision||0}"><div class="form-grid">${selectField('Standard *','standardId',state.data.standards.filter(t=>active(t)||t.id===s).map(t=>option(t.id,t.code+' · '+t.title,s)).join(''))}${selectField('Subtopik *','subtopicId',state.data.subtopics.filter(t=>t.standardId===s&&(active(t)||t.id===r?.subtopicId)).map(t=>option(t.id,t.code+' · '+t.title,r?.subtopicId||sub?.id)).join(''))}${field('Tajuk aktiviti / program / dokumen','title',r?.title||'','text',true,'span2')}${field('Tahun','year',r?.year||state.year,'number',true)}<div class="form-field"><label for="field-unit">Unit / Panitia</label><input id="field-unit" list="unit-list" name="unit" value="${esc(r?.unit||'')}" placeholder="Pilih atau taip nama unit"><datalist id="unit-list">${state.data.units.filter(active).map(t=>`<option value="${esc(t.name)}">`).join('')}</datalist></div>${field('Tarikh mula','startDate',r?.startDate||now,'date',true)}${field('Tarikh tamat','endDate',r?.endDate||now,'date',true)}${field('Nama pegawai','officer',r?.officer||state.user.name,'text',true)}${selectField('Akaun pegawai ditugaskan','assignedTo',state.data.users.filter(t=>active(t)&&(state.user.role!=='guru'||t.id===state.user.id)).map(t=>option(t.id,t.name,r?.assignedTo||state.user.id)).join(''))}${field('Objektif','objectives',r?.objectives||'','textarea',false,'span2')}${field('Kumpulan sasaran','target',r?.target||'','text',false,'span2')}${field('Ringkasan pelaksanaan','summary',r?.summary||'','textarea',false,'span2')}${field('Pencapaian / Impak','impact',r?.impact||'','textarea',false,'span2')}${field('Isu & Tindakan susulan','issues',r?.issues||'','textarea',false,'span2')}<div class="span2"><h3 style="font-size:13px;margin-bottom:9px">Senarai semak evidens</h3><div id="record-checklist">${checklistHTML(r?.subtopicId||sub?.id||state.data.subtopics.find(t=>t.standardId===s&&active(t))?.id,r?.checklist||[])}</div></div></div><div class="notice">Simpan draf dahulu untuk menambah fail atau pautan evidens. Untuk menghantar semakan, objektif dan ringkasan pelaksanaan perlu diisi.</div><div class="form-error" role="alert"></div><div class="modal-actions">${button('Batal','close-modal')}<button class="btn" type="submit" name="intent" value="draft">Simpan Draf</button><button class="btn primary" type="submit" name="intent" value="submit">Hantar untuk Semakan</button></div></form>`);
  if(r)$('#field-standardId').disabled=true;
}
function checklistHTML(subId,checked=[]){const sub=subBy(subId);return (sub?.checklist||[]).map(c=>`<label class="check-row"><input type="checkbox" name="checklist" value="${esc(c)}" ${checked.includes(c)?'checked':''}><span>${esc(c)}</span></label>`).join('')||'<p class="muted">Tiada senarai semak ditetapkan.</p>';}
function showEvidence(id){openModal('Tambah Evidens',`<form id="evidence-form" data-id="${id}">${selectField('Jenis evidens','type',option('link','Pautan dokumen','link')+option('file','Muat naik fail','link'))}${field('Nama evidens','name','','text',true)}<div id="evidence-input">${field('Pautan HTTPS','url','','url',true)}</div><div class="notice">Fail disimpan dalam folder Drive sekolah. Sistem mengekalkan kebenaran perkongsian Drive; pastikan penyemak mempunyai akses.</div>${actionsHTML('Tambah Evidens')}</form>`);}
function showReview(id,reopen=false){openModal(reopen?'Buka Semula Rekod':'Semakan Rekod',`<form id="review-form" data-id="${id}" data-reopen="${reopen}">${reopen?'':selectField('Keputusan semakan','status',option('Disahkan','Disahkan','Disahkan')+option('Perlu Pembetulan','Perlu Pembetulan','Disahkan'))}${field('Maklum balas','feedback','','textarea',reopen)}${actionsHTML(reopen?'Buka Semula':'Simpan Semakan')}</form>`);}
function showPassword(){openModal('Tukar Kata Laluan',`<form id="password-form">${state.user.forcePassword?'<div class="notice warning">Tukar kata laluan sementara untuk meneruskan penggunaan sistem.</div>':''}${field('Kata laluan semasa','oldPassword','','password',true)}${field('Kata laluan baharu (minimum 12 aksara)','newPassword','','password',true)}${field('Sahkan kata laluan baharu','confirmPassword','','password',true)}<div class="form-error" role="alert"></div><div class="modal-actions">${state.user.forcePassword?'':button('Batal','close-modal')}<button type="submit" class="btn primary">Tukar Kata Laluan</button></div></form>`);$('#field-oldPassword').minLength=1;$('#field-oldPassword').autocomplete='current-password';}
function showUser(id){const u=id?state.data.users.find(x=>x.id===id):null;openModal(u?'Sunting Pengguna':'Tambah Pengguna',`<form id="user-form" data-id="${esc(id||'')}"><div class="form-grid">${field('Nama penuh','name',u?.name||'','text',true)}${field('Nama pengguna','username',u?.username||'','text',true)}${selectField('Peranan','role',Object.entries(roleLabel).map(([v,l])=>option(v,l,u?.role||'guru')).join(''))}${selectField('Status akaun','active',option('true','Aktif',String(u?.active!==false))+option('false','Tidak aktif',String(u?.active!==false)))}${field(u?'Kata laluan sementara baharu (kosongkan untuk kekalkan)':'Kata laluan sementara (minimum 12 aksara)','password','','password',!u,'span2')}<div class="span2"><label style="font-size:11px;font-weight:700">Skop penyelaras</label>${state.data.standards.map(s=>`<label class="check-row"><input type="checkbox" name="scopes" value="${s.id}" ${u?.scopes?.includes(s.id)?'checked':''}>${esc(s.code+' · '+s.title)}</label>`).join('')}</div></div>${actionsHTML()}</form>`);}
function showMaster(table,id){const list=table==='Standard'?state.data.standards:table==='Subtopik'?state.data.subtopics:state.data.units;const v=list.find(x=>x.id===id)||{};openModal((id?'Sunting ':'Tambah ')+(table==='Unit_Panitia'?'Unit / Panitia':table),`<form id="master-form" data-id="${esc(id||'')}" data-table="${table}">${table!=='Standard'?selectField('Standard','standardId',state.data.standards.map(s=>option(s.id,s.code+' · '+s.title,v.standardId)).join('')):''}${table==='Unit_Panitia'?field('Nama unit / panitia','name',v.name||'','text',true):field('Kod','code',v.code||'','text',true)+field('Tajuk','title',v.title||'','text',true)+field('Penerangan','description',v.description||'','textarea')}${table==='Subtopik'?field('Pegawai bertanggungjawab','officer',v.officer||'')+field('Senarai semak evidens (satu item setiap baris)','checklist',(v.checklist||[]).join('\n'),'textarea'):''}${selectField('Status','active',option('true','Aktif',String(active(v)))+option('false','Tidak aktif',String(active(v))))}${actionsHTML()}</form>`);}
async function health(){const h=await api('health');toast(h.ready?'Sambungan SK@S berjaya · Versi '+h.version:'Apps Script tersedia. Jalankan setupSystem() dahulu.',!h.ready);}
async function csvReference(){
  openModal('CSV Rujukan',`<div id="csv-result"><p class="muted">Memuatkan data rujukan…</p></div>`);try{const r=await fetch(C.csvUrl,{cache:'no-store',credentials:'omit'});if(!r.ok)throw new Error('CSV tidak dapat dibaca.');const raw=await r.text();if(raw.trim().startsWith('<'))throw new Error('Pautan memulangkan halaman web dan bukannya CSV.');const rows=parseCSV(raw);const el=$('#csv-result');if(!el)return;el.innerHTML=rows.length?`<p class="muted" style="font-size:11px;margin-bottom:13px">${Math.max(0,rows.length-1)} baris data. Pratonton 20 baris pertama. CSV ini tidak diimport secara automatik.</p><div class="table-wrap"><table><thead><tr>${rows[0].map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.slice(1,21).map(row=>`<tr>${row.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('CSV masih kosong','Tambah data pada helaian sumber jika mahu menggunakan rujukan CSV.');}catch(e){if($('#csv-result'))$('#csv-result').innerHTML=`<div class="inline-error">${esc(e.message)}</div>`;}
}
function parseCSV(raw){const rows=[],text=raw.replace(/^\uFEFF/,''),row=[];let value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(value);value='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(x=>x!==''))rows.push(row.splice(0));else row.length=0;value='';}else value+=c;}row.push(value);if(row.some(x=>x!==''))rows.push(row);return rows;}
async function navigate(page){state.page=page;if(!['standard','subtopic'].includes(page)){state.standard='';state.subtopic='';}renderShell();window.scrollTo({top:0});if(page==='settings'&&state.settingsTab==='users'){state.data.users=await api('listUsers');if(state.page==='settings')renderPage();}}
async function refresh(){await load();if(state.page==='settings'&&state.settingsTab==='users'){state.data.users=await api('listUsers');renderPage();}}
function printHeader(title){return `<div class="print-header"><img class="print-logo" src="${logo()}" alt="Lencana sekolah"><div><h1>${esc(school())}</h1><h2>${esc(title)}</h2><div class="print-small">SK@S · Tahun ${esc(state.year)} · Dijana ${date(new Date().toISOString())}${state.demo?' · MOD DEMONSTRASI':''}</div></div></div>`;}
function printableRecord(r){return `<section><h2>${esc(r.title)}</h2><p class="print-small">Standard ${esc(standardBy(r.standardId)?.code||r.standardId)} · ${esc(subBy(r.subtopicId)?.code||'')} · ${esc(r.status)}</p><div class="print-grid"><p><b>Pegawai:</b> ${esc(r.officer)}<br><b>Unit:</b> ${esc(r.unit||'—')}</p><p><b>Tarikh:</b> ${date(r.startDate)} – ${date(r.endDate)}<br><b>Sasaran:</b> ${esc(r.target||'—')}</p></div>${[['Objektif',r.objectives],['Pelaksanaan',r.summary],['Pencapaian / Impak',r.impact],['Isu & Tindakan Susulan',r.issues]].map(([k,v])=>`<h3>${k}</h3><p>${esc(v||'—')}</p>`).join('')}<h3>Evidens</h3>${r.evidence.length?`<ol>${r.evidence.map(e=>`<li>${esc(e.name)}<br><a href="${safeURL(e.url)}">${esc(e.url)}</a></li>`).join('')}</ol>`:'<p>Belum ada evidens.</p>'}<h3>Senarai Semak</h3><p>${(subBy(r.subtopicId)?.checklist||[]).map(c=>(r.checklist.includes(c)?'✓ ':'○ ')+esc(c)).join('<br>')}</p>${state.data.reviews.filter(s=>s.recordId===r.id).length?`<h3>Sejarah Semakan</h3>${state.data.reviews.filter(s=>s.recordId===r.id).map(s=>`<p>${esc(s.status)} · ${esc(s.reviewerName)} · ${date(s.createdAt)}<br>${esc(s.feedback||'—')}</p>`).join('')}`:''}<p class="signature"><b>Disediakan oleh:</b> ${esc(r.officer)}</p></section>`;}
async function printReport(type,id){
  let rs=filteredRecords(),title='',html='',landscape=false;
  if(type==='record'){const r=recordBy(id);if(!r)return;title='Laporan Pelaksanaan';html=printableRecord(r);}
  else if(type==='summary'){title='Rumusan Pengurusan Sekolah';html=`<p>Ringkasan berdasarkan tahun dan penapis yang dipilih. ${rs.length} rekod.</p><table><thead><tr><th>Standard</th><th>Jumlah</th>${statuses.map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${state.data.standards.map(s=>{const list=rs.filter(r=>r.standardId===s.id);return `<tr><td>${esc(s.code+' · '+s.title)}</td><td>${list.length}</td>${statuses.map(st=>`<td>${list.filter(r=>r.status===st).length}</td>`).join('')}</tr>`;}).join('')}</tbody></table><h3>Liputan Subtopik (berdasarkan penapis)</h3>${state.data.standards.filter(active).map(s=>{const subs=state.data.subtopics.filter(t=>t.standardId===s.id&&active(t)),done=subs.filter(t=>rs.some(r=>r.subtopicId===t.id&&r.status==='Disahkan')).length;return `<p>${esc(s.title)}: ${done}/${subs.length} subtopik mempunyai rekod disahkan (${subs.length?Math.round(done/subs.length*100):0}%).</p>`;}).join('')}<p class="print-small">Liputan = subtopik dengan sekurang-kurangnya satu rekod disahkan ÷ jumlah subtopik aktif × 100%. Berdasarkan rekod yang boleh diakses; bukan skor rasmi SK@S.</p>`;}
  else if(type==='evidence'){title='Daftar Evidens';landscape=true;const ev=rs.flatMap(r=>r.evidence.map(e=>({...e,title:r.title,code:subBy(r.subtopicId)?.code})));html=`<table><thead><tr><th style="width:5%">Bil.</th><th>Rekod / Subtopik</th><th>Nama Evidens</th><th style="width:38%">Pautan</th></tr></thead><tbody>${ev.map((e,i)=>`<tr><td>${i+1}</td><td>${esc(e.title)}<br>${esc(e.code)}</td><td>${esc(e.name)}</td><td>${esc(e.url)}</td></tr>`).join('')}</tbody></table>${ev.length?'':'<p>Belum ada evidens.</p>'}`;}
  else if(type==='program'){title='Laporan Program';html=rs.map((r,i)=>`<div${i?' style="break-before:page"':''}>${printableRecord(r)}</div>`).join('')||'<p>Tiada rekod.</p>';}
  else{title=type==='incomplete'?'Rekod Belum Lengkap':'Senarai Rekod Pelaksanaan';landscape=true;if(type==='incomplete')rs=rs.filter(r=>r.status!=='Disahkan'||!r.evidence.length||(subBy(r.subtopicId)?.checklist||[]).some(c=>!r.checklist.includes(c)));html=`<table><thead><tr><th style="width:4%">Bil.</th><th style="width:30%">Tajuk / Subtopik</th><th>Pegawai</th><th>Tarikh</th><th>Evidens</th><th>Status</th></tr></thead><tbody>${rs.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.title)}<br>${esc(subBy(r.subtopicId)?.code||'')}</td><td>${esc(r.officer)}</td><td>${date(r.startDate)}</td><td>${r.evidence.length}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table>${rs.length?'':'<p>Tiada rekod.</p>'}`;}
  $('#print-area').innerHTML=printHeader(title)+html;let style=$('#print-orientation');if(!style){style=document.createElement('style');style.id='print-orientation';document.head.append(style);}style.textContent=`@media print{@page{size:A4 ${landscape?'landscape':'portrait'};margin:13mm}}`;
  if(document.fonts?.ready)await document.fonts.ready;const img=$('#print-area img');if(img&&!img.complete)await Promise.race([new Promise(resolve=>{img.onload=resolve;img.onerror=resolve;}),new Promise(resolve=>setTimeout(resolve,1800))]);window.print();
}
async function install(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else openModal('Pasang SK@S pada Peranti',`<div class="install-info"><p>Gunakan pautan HTTPS sistem yang telah dideploy di GitHub Pages.</p><ol><li><b>Android / Chrome:</b> Buka menu ⋮, kemudian pilih <b>Install app / Pasang aplikasi</b> atau <b>Add to Home screen</b>.</li><li><b>iPhone / iPad (Safari):</b> Tekan butang Kongsi, pilih <b>Add to Home Screen</b>, kemudian <b>Add</b>.</li><li><b>Komputer (Chrome / Edge):</b> Pilih ikon pemasangan di bar alamat jika tersedia.</li></ol><div class="notice">PWA menyimpan kerangka aplikasi untuk pembukaan luar talian. Log masuk, rekod dan simpanan memerlukan Internet. Data sekolah tidak disimpan dalam cache PWA.</div>${button('Tutup','close-modal')}</div>`);}
// Satu pengendali peristiwa untuk paparan dinamik; tiada data pengguna dimasukkan sebagai kod.
document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-action]');if(!b||submitting)return;const a=b.dataset.action,id=b.dataset.id;
  try{
    if(a==='nav')return navigate(b.dataset.page);
    if(a==='nav-standards')return navigate('standards');if(a==='nav-records')return navigate('records');
    if(a==='menu')return document.body.classList.toggle('menu-open');if(a==='close-modal')return closeModal();
    if(a==='demo'){state.demo=true;state.data=demoData();state.user=state.data.user;state.token='demo';state.page='dashboard';state.year=String(new Date().getFullYear());return renderShell();}
    if(a==='health')return await health();if(a==='install')return await install();
    if(a==='logout'){if(!state.demo){try{await api('logout');}catch{}}state.demo=false;state.token='';state.user=null;state.data=null;forget();document.body.classList.remove('menu-open');return renderLogin();}
    if(a==='refresh'){await refresh();return toast('Data dimuat semula.');}
    if(a==='standard'){state.standard=id;state.subtopic='';state.page='standard';return renderShell();}
    if(a==='subtopic'){state.subtopic=id;state.standard=subBy(id).standardId;state.page='subtopic';return renderShell();}
    if(a==='detail'){state.record=id;state.page='detail';return renderShell();}
    if(a==='metric'){Object.keys(state.filters).forEach(k=>state.filters[k]='');state.filters.status=b.dataset.status;return navigate('records');}
    if(a==='create')return showRecordForm();if(a==='edit')return showRecordForm(id);
    if(a==='evidence')return showEvidence(id);if(a==='review')return showReview(id);if(a==='reopen')return showReview(id,true);
    if(a==='password')return showPassword();if(a==='new-user')return showUser();if(a==='edit-user')return showUser(id);
    if(a==='new-master'||a==='edit-master')return showMaster(b.dataset.table,id);
    if(a==='settings-tab'){state.settingsTab=id;if(id==='users')state.data.users=await api('listUsers');return renderPage();}
    if(a==='csv')return await csvReference();
    if(a==='print-list')return await printReport('list');if(a==='print-record')return await printReport('record',id);if(a==='report')return await printReport(b.dataset.type);
    if(a==='delete-record'){const r=recordBy(id);return openModal('Padam Rekod',`<p>Padam rekod <b>${esc(r.title)}</b> bersama rujukan evidens dan semakannya?</p><div class="notice warning">Fail asal di Google Drive dikekalkan. Rekod yang dipadam tidak boleh dipulihkan melalui aplikasi.</div><form id="delete-form" data-id="${id}">${actionsHTML('Ya, Padam Rekod')}</form>`);}
    if(a==='remove-evidence')return openModal('Buang Evidens',`<p>Buang evidens ini daripada rekod? Fail asal Google Drive dikekalkan.</p><form id="remove-evidence-form" data-id="${id}" data-record="${b.dataset.record}">${actionsHTML('Buang Evidens')}</form>`);
    if(a==='submit-record'){const r=recordBy(id);b.disabled=true;try{await api('saveRecord',{record:{...r,submit:true}});await refresh();return toast('Rekod dihantar untuk semakan.');}finally{b.disabled=false;}}
  }catch(err){toast(err.message,true);}
});
document.addEventListener('change',e=>{
  const el=e.target;
  if(el.id==='school-year'){state.year=el.value;return renderShell();}
  if(el.dataset.filter){state.filters[el.dataset.filter]=el.value;if(el.dataset.filter==='standard'){state.filters.subtopic='';const sub=$('#f-subtopic');if(sub)sub.innerHTML=option('','Semua Subtopik','')+state.data.subtopics.filter(t=>!el.value||t.standardId===el.value).map(t=>option(t.id,t.code+' · '+t.title,'')).join('');}if($('#records-result'))$('#records-result').innerHTML=recordsTable(filteredRecords());}
  if(el.id==='field-standardId'&&$('#record-form')){const list=state.data.subtopics.filter(t=>t.standardId===el.value&&active(t));$('#field-subtopicId').innerHTML=list.map(t=>option(t.id,t.code+' · '+t.title,'')).join('');$('#record-checklist').innerHTML=checklistHTML(list[0]?.id);}
  if(el.id==='field-subtopicId'&&$('#record-form'))$('#record-checklist').innerHTML=checklistHTML(el.value);
  if(el.name==='type'&&$('#evidence-form'))$('#evidence-input').innerHTML=el.value==='link'?field('Pautan HTTPS','url','','url',true):`<div class="form-field"><label for="evidence-file">Fail (maksimum 5 MB)</label><input id="evidence-file" type="file" name="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.xls,.xlsx,.ppt,.pptx" required><small>PDF, gambar atau dokumen Microsoft Office.</small></div>`;
});
document.addEventListener('input',e=>{const el=e.target;if(['search','officer'].includes(el.dataset.filter)){state.filters[el.dataset.filter]=el.value;if($('#records-result'))$('#records-result').innerHTML=recordsTable(filteredRecords());}});
document.addEventListener('submit',async e=>{
  const form=e.target;if(!form.id)return;e.preventDefault();if(submitting)return;
  if(form.id==='global-search'){state.filters.search=form.elements.query.value;return navigate('records');}
  const d=Object.fromEntries(new FormData(form)),intent=e.submitter?.value;submitting=true;const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);const errorNode=$('.form-error',form)||$('#login-error');if(errorNode)errorNode.textContent='';
  try{
    if(form.id==='login-form'){state.demo=false;const result=await api('login',{username:d.username,password:d.password});if(!result?.token||!result.user)throw new Error('Format API tidak sepadan. Deploy Code.gs SK@S yang dibekalkan terlebih dahulu.');state.token=result.token;state.user=result.user;remember();state.page='dashboard';if(state.user.forcePassword)showPassword();else{await load();state.year=String(state.data.settings.year||state.year);renderShell();}return;}
    if(form.id==='password-form'){if(d.newPassword!==d.confirmPassword)throw new Error('Pengesahan kata laluan tidak sepadan.');state.user=await api('changePassword',{oldPassword:d.oldPassword,newPassword:d.newPassword});remember();$('#modal').close();await load();toast('Kata laluan berjaya ditukar.');return;}
    if(form.id==='record-form'){const record={...d,id:form.dataset.id,revision:form.dataset.revision,standardId:form.elements.standardId.value,checklist:[...form.querySelectorAll('[name="checklist"]:checked')].map(x=>x.value),submit:intent==='submit'};const saved=await api('saveRecord',{record});$('#modal').close();state.record=saved.id;state.page='detail';await refresh();toast(record.submit?'Rekod dihantar untuk semakan.':'Draf disimpan. Anda boleh menambah evidens.');return;}
    if(form.id==='evidence-form'){const payload={recordId:form.dataset.id,name:d.name};if(d.type==='link')payload.url=d.url;else{const f=form.elements.file.files[0];if(!f)throw new Error('Pilih fail dahulu.');if(f.size>5*1024*1024)throw new Error('Saiz fail maksimum ialah 5 MB.');payload.name=d.name||f.name;payload.mimeType=f.type||mimeFor(f.name);payload.base64=await fileBase64(f);}await api('addEvidence',payload);$('#modal').close();await refresh();toast('Evidens berjaya ditambah.');return;}
    if(form.id==='review-form'){await api(form.dataset.reopen==='true'?'reopenRecord':'reviewRecord',{id:form.dataset.id,status:d.status,feedback:d.feedback});$('#modal').close();await refresh();toast('Semakan disimpan.');return;}
    if(form.id==='delete-form'){await api('deleteRecord',{id:form.dataset.id});$('#modal').close();state.page='records';await refresh();toast('Rekod dipadam.');return;}
    if(form.id==='remove-evidence-form'){await api('removeEvidence',{id:form.dataset.id,recordId:form.dataset.record});$('#modal').close();await refresh();toast('Evidens dibuang daripada rekod.');return;}
    if(form.id==='user-form'){await api('saveUser',{user:{...d,id:form.dataset.id,active:d.active==='true',scopes:[...form.querySelectorAll('[name="scopes"]:checked')].map(x=>x.value)}});$('#modal').close();await refresh();toast('Pengguna disimpan.');return;}
    if(form.id==='master-form'){await api('saveMaster',{table:form.dataset.table,item:{...d,id:form.dataset.id,active:d.active==='true',checklist:(d.checklist||'').split('\n').map(x=>x.trim()).filter(Boolean)}});$('#modal').close();await refresh();toast('Tetapan disimpan.');return;}
    if(form.id==='school-form'){await api('saveSettings',{settings:d});await refresh();toast('Tetapan sekolah disimpan.');return;}
  }catch(err){if(errorNode&&errorNode.isConnected)errorNode.textContent=err.message;else toast(err.message,true);}finally{submitting=false;buttons.forEach(b=>b.disabled=false);}
});
function fileBase64(f){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(new Error('Fail tidak dapat dibaca.'));r.readAsDataURL(f);});}
function mimeFor(name){return ({pdf:'application/pdf',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',doc:'application/msword',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xls:'application/vnd.ms-excel',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',ppt:'application/vnd.ms-powerpoint',pptx:'application/vnd.openxmlformats-officedocument.presentationml.presentation'})[name.split('.').pop().toLowerCase()]||'application/octet-stream';}
function demoApi(action,p={}){
  const data=state.data;if(action==='health')return {app:'SKAS',ready:true,version:C.version};if(action==='bootstrap')return data;if(action==='listUsers')return data.users;if(action==='changePassword'){state.user.forcePassword=false;return state.user;}
  const id=()=>crypto.randomUUID?crypto.randomUUID():'D-'+Date.now(),now=()=>new Date().toISOString();
  if(action==='saveRecord'){const old=data.records.find(r=>r.id===p.record.id);const r={...old,...p.record,id:old?.id||id(),ownerId:old?.ownerId||state.user.id,evidence:old?.evidence||[],status:p.record.submit?'Dihantar':'Draf',revision:Number(old?.revision||0)+1,createdAt:old?.createdAt||now(),updatedAt:now()};if(!r.title)throw new Error('Tajuk diperlukan.');if(r.submit&&(!r.objectives||!r.summary))throw new Error('Isi objektif dan ringkasan dahulu.');if(old)Object.assign(old,r);else data.records.push(r);return r;}
  if(action==='deleteRecord'){data.records=data.records.filter(r=>r.id!==p.id);return true;}
  if(action==='reviewRecord'||action==='reopenRecord'){const r=recordBy(p.id);r.status=action==='reopenRecord'?'Perlu Pembetulan':p.status;r.feedback=p.feedback;r.revision++;data.reviews.push({id:id(),recordId:r.id,status:r.status,feedback:p.feedback,reviewerName:state.user.name,createdAt:now()});return r;}
  if(action==='addEvidence'){const r=recordBy(p.recordId);if(!p.url)throw new Error('Mod demo menyokong pautan sahaja. Muat naik fail tersedia selepas sambungan sebenar.');r.evidence.push({id:id(),name:p.name,url:p.url,mimeType:'link',createdAt:now()});r.revision++;return r;}
  if(action==='removeEvidence'){const r=recordBy(p.recordId);r.evidence=r.evidence.filter(e=>e.id!==p.id);r.revision++;return r;}
  if(action==='saveUser'){const u={...p.user,id:p.user.id||id(),forcePassword:true};delete u.password;const old=data.users.find(x=>x.id===u.id);if(old)Object.assign(old,u);else data.users.push(u);return u;}
  if(action==='saveMaster'){const list=p.table==='Standard'?data.standards:p.table==='Subtopik'?data.subtopics:data.units;const v={...p.item,id:p.item.id||id()},old=list.find(x=>x.id===v.id);if(old)Object.assign(old,v);else list.push(v);return v;}
  if(action==='saveSettings'){data.settings=p.settings;return p.settings;}
  if(action==='logout')return true;throw new Error('Tindakan demo tidak tersedia.');
}
