async function init(){
 window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
 window.addEventListener('online',()=>{if(state.data)renderShell();toast('Sambungan Internet dipulihkan.');});
 window.addEventListener('offline',()=>{if(state.data)renderShell();toast('Luar talian. Simpanan memerlukan Internet.',true);});
 $('#modal').addEventListener('cancel',e=>{if(state.user?.forcePassword)e.preventDefault();});
 try{const saved=JSON.parse(sessionStorage.getItem('skas-session')||'null');if(saved?.token&&saved.user){state.token=saved.token;state.user=saved.user;}}catch{}
 renderLogin();
 if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>toast('PWA belum tersedia. Semak fail sw.js pada hosting.',true));
 if(state.user&&state.token){if(state.user.forcePassword)showPassword();else try{await load();}catch(e){toast(e.message,true);}}
}
init();
